class Solution {
    public int leastBricks(List<List<Integer>> wall){
        Map<Long,Integer> counts=new HashMap<>();
        int maximum=0;
        for(List<Integer> row:wall){
            long position=0;
            for(int i=0;i+1<row.size();i++){
                position+=row.get(i);
                int count=counts.getOrDefault(position,0)+1;
                counts.put(position,count);
                maximum=Math.max(maximum,count);
            }
        }
        return wall.size()-maximum;
    }
}

code.kotlin:
class Solution {
    fun leastBricks(wall:List<List<Int>>):Int{
        val counts=hashMapOf<Long,Int>();
        var maximum=0;
        for(row in wall){
            var position=0L;
            for(i in 0 until row.lastIndex){
                position+=row[i];
                val count=(counts[position]?:0)+1;
                counts[position]=count;
                maximum=maxOf(maximum,count)
            }
        };
        return wall.size-maximum
    }
}

code.cpp:
class Solution {
    public: int leastBricks(vector<vector<int>>& wall){
        unordered_map<long long,int> counts;
        int maximum=0;
        for(auto& row:wall){
            long long position=0;
            for(int i=0;i+1<(int)row.size();++i){
                position+=row[i];
                maximum=max(maximum,++counts[position]);
            }
        }
        return wall.size()-maximum;
    }
};
